const PARTIAL = process.env.PARTIAL === "1"
const missing = SUBJECTS.filter(s => !D[s])
if (missing.length && !PARTIAL) throw new Error(`missing subjects: ${missing.join(" | ")}`)
if (missing.length) console.log(`PARTIAL RUN — ${SUBJECTS.length - missing.length} of ${SUBJECTS.length} subjects present`)
const extra = Object.keys(D).filter(s => !SUBJECTS.includes(s))
if (extra.length) throw new Error(`unknown subjects: ${extra.join(" | ")}`)

const coverage_profiles = SUBJECTS.filter(subject => D[subject]).map(subject => ({
  subject,
  tuples: D[subject].map(([episode_object, time_place_scope, mechanism, evidence_lens]) => ({
    episode_object, time_place_scope, mechanism, evidence_lens,
  })),
}))

const dedup = key => {
  const seen = new Set()
  const out = []
  for (const profile of coverage_profiles) {
    for (const tuple of profile.tuples) {
      if (!seen.has(tuple[key])) { seen.add(tuple[key]); out.push(tuple[key]) }
    }
  }
  return out
}

