// ── audit ───────────────────────────────────────────────────────────────────

const problems = []
const FORBIDDEN = ["youtube", "tiktok", "instagram", "facebook", "microsoft", "photoshop", "illustrator", "vimeo", "twitch"]
const UNSAFE_REFERENCE = /(?:\b[a-z][a-z0-9+.-]*:\S+|(?:^|[\s(])\/\/\S+|\bwww\.\S+|\b(?:[a-z0-9-]+\.)+[a-z]{2,}(?:\/\S*)?)/i
const ROUTING = /\b(?:provider_id|model_id|engine_id)\b|\bprovider\s*(?::|=)\s*[^\s]+|\bmodel\s*(?::|=)\s*[^\s]+/i
const DIGIT_DATE = /\b\d{1,2}\s+(?:January|February|March|April|May|June|July|August|September|October|November|December)\b/i

const LIMITS = { episode_object: [40, 140], time_place_scope: [40, 140], mechanism: [40, 160], evidence_lens: [40, 160] }
const KEYS = ["episode_object", "time_place_scope", "mechanism", "evidence_lens"]

// Identifiers are validated by the schema's qualifiedId rule, not by safeText.
const ID_FIELDS = new Set(["document.id", "document.compatible_formula_ids[0]"])
const walk = (value, where) => {
  if (typeof value === "string") {
    if (ID_FIELDS.has(where)) return
    const lower = value.toLowerCase()
    for (const word of FORBIDDEN) if (lower.includes(word)) problems.push(`${where}: forbidden word "${word}" -> ${value}`)
    const cap = where === "document.prompt_context" ? 1500 : 1000
    if (value.length < 1 || value.length > cap) problems.push(`${where}: length ${value.length} out of 1..${cap}`)
    if (UNSAFE_REFERENCE.test(value)) problems.push(`${where}: URI-like reference -> ${value}`)
    if (ROUTING.test(value)) problems.push(`${where}: routing directive -> ${value}`)
    if (DIGIT_DATE.test(value)) problems.push(`${where}: exact date -> ${value}`)
  } else if (Array.isArray(value)) {
    value.forEach((entry, index) => walk(entry, `${where}[${index}]`))
  } else if (value && typeof value === "object") {
    for (const [key, entry] of Object.entries(value)) walk(entry, `${where}.${key}`)
  }
}
walk(document, "document")

if (coverage_profiles.length !== 50) problems.push(`expected 50 profiles, got ${coverage_profiles.length}`)
const fullTuples = new Set()
const objectMechanism = new Set()
const declared = {
  episode_object: new Set(document.episode_objects),
  time_place_scope: new Set(document.time_place_scopes),
  mechanism: new Set(document.mechanisms),
  evidence_lens: new Set(document.evidence_lenses),
}
for (const profile of coverage_profiles) {
  if (profile.tuples.length !== 20) problems.push(`${profile.subject}: ${profile.tuples.length} tuples, expected 20`)
  const objects = new Set()
  const mechanisms = new Set()
  for (const [index, tuple] of profile.tuples.entries()) {
    for (const key of KEYS) {
      const value = tuple[key]
      const [lo, hi] = LIMITS[key]
      if (value.length < lo || value.length > hi) problems.push(`${profile.subject}#${index + 1} ${key}: ${value.length} chars (want ${lo}-${hi}) -> ${value}`)
      if (!declared[key].has(value)) problems.push(`${profile.subject}#${index + 1} ${key}: not in top-level list`)
    }
    objects.add(tuple.episode_object)
    mechanisms.add(tuple.mechanism)
    const full = KEYS.map(key => tuple[key]).join(" ||| ")
    if (fullTuples.has(full)) problems.push(`duplicate full tuple: ${profile.subject}#${index + 1}`)
    fullTuples.add(full)
    const pair = `${tuple.episode_object} ||| ${tuple.mechanism}`
    if (objectMechanism.has(pair)) problems.push(`duplicate object|mechanism pair: ${profile.subject}#${index + 1} -> ${pair}`)
    objectMechanism.add(pair)
  }
  if (objects.size !== profile.tuples.length) problems.push(`${profile.subject}: repeated episode_object within subject`)
  if (mechanisms.size !== profile.tuples.length) problems.push(`${profile.subject}: repeated mechanism within subject`)
}

console.log(`subjects: ${document.subjects.length}`)
console.log(`profiles: ${coverage_profiles.length}`)
console.log(`tuples: ${coverage_profiles.reduce((sum, profile) => sum + profile.tuples.length, 0)}`)
console.log(`episode_objects: ${document.episode_objects.length}`)
console.log(`time_place_scopes: ${document.time_place_scopes.length}`)
console.log(`mechanisms: ${document.mechanisms.length}`)
console.log(`evidence_lenses: ${document.evidence_lenses.length}`)
console.log(`bytes: ${statSync(outPath).size}`)
if (problems.length) {
  console.log(`AUDIT FAILED (${problems.length})`)
  for (const problem of problems.slice(0, 60)) console.log(`  - ${problem}`)
} else {
  console.log("AUDIT OK")
}
